import os
import sys
import tempfile
import textwrap
from collections import defaultdict
from pathlib import Path
from types import SimpleNamespace

sys.dont_write_bytecode = True

import torch
import torch.distributed as dist
import torch.multiprocessing as mp
from accelerate import Accelerator
from accelerate.utils import gather_object


SOURCE = Path("/workspace/src/trl/trainer/grpo_trainer.py").read_text()
START = SOURCE.index("        # Flush user-logged metrics (from log_metric)")
END = SOURCE.index("        if images is not None", START)
FLUSH_BLOCK = textwrap.dedent(SOURCE[START:END])


def flush(trainer, mode="train"):
    device = trainer.accelerator.device
    self = trainer
    exec(FLUSH_BLOCK, {"self": self, "mode": mode, "device": device, "torch": torch, "gather_object": gather_object})


def check(trainer, rank, pending, expected):
    trainer._pending_metrics = defaultdict(list, pending)
    trainer._metrics = {"train": defaultdict(list), "eval": defaultdict(list)}
    flush(trainer)
    actual = dict(trainer._metrics["train"])
    assert set(actual) == set(expected), (rank, actual, expected)
    for key, value in expected.items():
        assert len(actual[key]) == 1, (rank, key, actual[key])
        assert abs(actual[key][0] - value) < 1e-7, (rank, key, actual[key], value)
    assert not trainer._pending_metrics


def worker(rank, init_file):
    dist.init_process_group("gloo", init_method=f"file://{init_file}", rank=rank, world_size=2)
    try:
        trainer = SimpleNamespace(accelerator=Accelerator(cpu=True))
        if rank == 0:
            pending = {"answer_parse_rate": [2.0 / 3.0]}
        else:
            pending = {}
        check(trainer, rank, pending, {"answer_parse_rate": 2.0 / 3.0})

        if rank == 0:
            pending = {"answer_parse_rate": [0.5, 1.0], "rank0_only": [7.0]}
            expected = {"answer_parse_rate": 0.75, "rank0_only": 7.0, "rank1_only": 11.0}
        else:
            pending = {"rank1_only": [11.0]}
            expected = {"answer_parse_rate": 0.75, "rank0_only": 7.0, "rank1_only": 11.0}
        check(trainer, rank, pending, expected)
        dist.barrier()
        if rank == 0:
            print("PASS: rank-local metrics synchronize on both ranks; absent contributions are ignored")
    finally:
        dist.destroy_process_group()


if __name__ == "__main__":
    fd, path = tempfile.mkstemp(prefix="trl-metric-test-")
    os.close(fd)
    os.unlink(path)
    try:
        mp.spawn(worker, args=(path,), nprocs=2, join=True)
    finally:
        if os.path.exists(path):
            os.unlink(path)
